#include <bits/stdc++.h>

using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> a(6, 0), b(6, 0);

    for (int i = 0; i < n; ++i) {
        int t;
        cin >> t;
        ++a[t];
    }

    for (int i = 0; i < n; ++i) {
        int t;
        cin >> t;
        ++b[t];
    }

    int rs = 0, rs1 = 0;

    for (int i = 1; i < 6; ++i) {
        if ((a[i] + b[i]) % 2 != 0) {
            cout << -1;
            return 0;
        }

        int m = (a[i] + b[i]) / 2;
        rs += abs(a[i] - m);
        rs1 += abs(b[i] - m);
    }

    cout << (rs == rs1 ? rs / 2 : -1);
    return 0;
}

